"""
NutriCheck - Person 2
Dataset Validation

Validates the already-preprocessed medical transcription dataset.

This module does NOT perform aggressive text cleaning.
It checks whether the dataset is suitable for downstream NLP.
"""

from __future__ import annotations

import logging
from pathlib import Path
from typing import Any

import pandas as pd


# ============================================================
# Logging
# ============================================================

logger = logging.getLogger(__name__)


# ============================================================
# Dataset Validator
# ============================================================

class MedicalDatasetValidator:
    """
    Validate the NutriCheck medical transcription dataset.
    """

    REQUIRED_COLUMNS = {
        "description",
        "medical_specialty",
        "sample_name",
        "transcription",
        "keywords",
    }

    TEXT_COLUMNS = [
        "description",
        "medical_specialty",
        "sample_name",
        "transcription",
        "keywords",
    ]

    def __init__(self, dataset_path: str | Path) -> None:
        self.dataset_path = Path(dataset_path)

    # ========================================================
    # Load Dataset
    # ========================================================

    def load(self) -> pd.DataFrame:
        """
        Load the CSV dataset.
        """

        if not self.dataset_path.exists():
            raise FileNotFoundError(
                f"Dataset not found: {self.dataset_path}"
            )

        if not self.dataset_path.is_file():
            raise ValueError(
                f"Dataset path is not a file: {self.dataset_path}"
            )

        if self.dataset_path.suffix.lower() != ".csv":
            raise ValueError(
                f"Expected a CSV dataset, got: "
                f"{self.dataset_path.suffix}"
            )

        logger.info(
            "Loading dataset: %s",
            self.dataset_path,
        )

        dataframe = pd.read_csv(
            self.dataset_path
        )

        logger.info(
            "Dataset loaded: %d rows, %d columns",
            len(dataframe),
            len(dataframe.columns),
        )

        return dataframe

    # ========================================================
    # Validate Columns
    # ========================================================

    def validate_columns(
        self,
        dataframe: pd.DataFrame,
    ) -> dict[str, Any]:
        """
        Check whether all required columns exist.
        """

        actual_columns = set(
            dataframe.columns
        )

        missing_columns = (
            self.REQUIRED_COLUMNS
            - actual_columns
        )

        return {
            "valid": len(missing_columns) == 0,
            "required_columns": sorted(
                self.REQUIRED_COLUMNS
            ),
            "missing_columns": sorted(
                missing_columns
            ),
            "actual_columns": list(
                dataframe.columns
            ),
        }

    # ========================================================
    # Missing Values
    # ========================================================

    def missing_values(
        self,
        dataframe: pd.DataFrame,
    ) -> dict[str, int]:
        """
        Count missing values in every column.
        """

        return {
            column: int(
                dataframe[column].isna().sum()
            )
            for column in dataframe.columns
        }

    # ========================================================
    # Duplicate Rows
    # ========================================================

    def duplicate_count(
        self,
        dataframe: pd.DataFrame,
    ) -> int:
        """
        Count duplicate rows.
        """

        return int(
            dataframe.duplicated().sum()
        )

    # ========================================================
    # Empty Text Fields
    # ========================================================

    def empty_text_counts(
        self,
        dataframe: pd.DataFrame,
    ) -> dict[str, int]:
        """
        Count empty strings in important text columns.

        Missing values are converted to empty strings
        for this check.
        """

        result: dict[str, int] = {}

        for column in self.TEXT_COLUMNS:

            if column not in dataframe.columns:
                continue

            values = (
                dataframe[column]
                .fillna("")
                .astype(str)
                .str.strip()
            )

            result[column] = int(
                (values == "").sum()
            )

        return result

    # ========================================================
    # Dataset Shape
    # ========================================================

    def dataset_shape(
        self,
        dataframe: pd.DataFrame,
    ) -> dict[str, int]:
        """
        Return dataset dimensions.
        """

        return {
            "rows": int(
                dataframe.shape[0]
            ),
            "columns": int(
                dataframe.shape[1]
            ),
        }

    # ========================================================
    # Full Validation
    # ========================================================

    def validate(self) -> dict[str, Any]:
        """
        Perform the complete validation.
        """

        dataframe = self.load()

        column_result = (
            self.validate_columns(
                dataframe
            )
        )

        shape_result = (
            self.dataset_shape(
                dataframe
            )
        )

        report = {
            "dataset": str(
                self.dataset_path
            ),

            "rows": shape_result[
                "rows"
            ],

            "columns": shape_result[
                "columns"
            ],

            "column_validation": (
                column_result
            ),

            "missing_values": (
                self.missing_values(
                    dataframe
                )
            ),

            "duplicate_rows": (
                self.duplicate_count(
                    dataframe
                )
            ),

            "empty_text_fields": (
                self.empty_text_counts(
                    dataframe
                )
            ),
        }

        # The dataset is considered structurally valid
        # when all required columns are present.
        #
        # Missing values are reported but are NOT
        # automatically treated as a reason to reject
        # the dataset.

        report["valid"] = (
            column_result["valid"]
            and "transcription"
            not in column_result[
                "missing_columns"
            ]
        )

        return report


# ============================================================
# Find Uploaded Dataset
# ============================================================

def find_dataset() -> Path:
    """
    Find the medical_transcriptions CSV.

    FIX (NLP integration): the original version only looked in Google Colab's /content
    folder, so it failed on every normal computer even though the README says the data
    lives in data/raw/. The search order is now:

        1. environment variable NUTRICHECK_DATASET (a path to the CSV)
        2. <project root>/data/raw/            (the location documented in the README)
        3. the current working directory
        4. /content                            (Google Colab, the original behaviour)

    in each folder it accepts  medical_transcriptions.csv,
    medical_transcriptions.csv.csv (accidental double extension) and
    medical_transcriptions*.csv.
    """
    import os

    names = ["medical_transcriptions.csv", "medical_transcriptions.csv.csv"]

    env = os.getenv("NUTRICHECK_DATASET")
    if env:
        env_path = Path(env)
        if env_path.is_file():
            return env_path

    project_root = Path(__file__).resolve().parents[2]
    folders = [
        project_root / "data" / "raw",
        Path.cwd(),
        Path("/content"),
    ]

    for folder in folders:
        for filename in names:
            candidate = folder / filename
            if candidate.is_file():
                return candidate
        if folder.is_dir():
            matches = sorted(folder.glob("medical_transcriptions*.csv"))
            if matches:
                return matches[0]

    searched = "\n".join(f"  {f}" for f in folders)
    raise FileNotFoundError(
        "Could not find the medical transcription dataset.\n"
        "Put medical_transcriptions.csv in data/raw/ or set NUTRICHECK_DATASET.\n"
        f"Searched:\n{searched}"
    )


# ============================================================
# Print Validation Report
# ============================================================

def print_report(
    report: dict[str, Any],
) -> None:
    """
    Print the validation report in a readable format.
    """

    print()
    print("=" * 70)
    print(
        "NutriCheck - Person 2 "
        "Dataset Validation"
    )
    print("=" * 70)

    print()
    print(
        f"Dataset: {report['dataset']}"
    )

    print(
        f"Rows: {report['rows']}"
    )

    print(
        f"Columns: {report['columns']}"
    )

    print()
    print("-" * 70)
    print("COLUMN VALIDATION")
    print("-" * 70)

    column_validation = (
        report["column_validation"]
    )

    print(
        f"Valid columns: "
        f"{column_validation['valid']}"
    )

    print()
    print("Required columns:")

    for column in (
        column_validation[
            "required_columns"
        ]
    ):
        print(
            f"  ✓ {column}"
        )

    print()
    print("Actual columns:")

    for column in (
        column_validation[
            "actual_columns"
        ]
    ):
        print(
            f"  • {column}"
        )

    print()

    if column_validation[
        "missing_columns"
    ]:

        print(
            "Missing required columns:"
        )

        for column in (
            column_validation[
                "missing_columns"
            ]
        ):
            print(
                f"  ✗ {column}"
            )

    else:

        print(
            "Missing required columns: None"
        )

    print()
    print("-" * 70)
    print("MISSING VALUES")
    print("-" * 70)

    for column, count in (
        report["missing_values"].items()
    ):
        print(
            f"  {column}: {count}"
        )

    print()
    print("-" * 70)
    print("DUPLICATE ROWS")
    print("-" * 70)

    print(
        f"Duplicate rows: "
        f"{report['duplicate_rows']}"
    )

    print()
    print("-" * 70)
    print("EMPTY TEXT FIELDS")
    print("-" * 70)

    for column, count in (
        report[
            "empty_text_fields"
        ].items()
    ):
        print(
            f"  {column}: {count}"
        )

    print()
    print("-" * 70)
    print("FINAL VALIDATION")
    print("-" * 70)

    if report["valid"]:

        print(
            "✓ DATASET VALID"
        )

    else:

        print(
            "✗ DATASET INVALID"
        )

    print()
    print("=" * 70)


# ============================================================
# Main
# ============================================================

if __name__ == "__main__":

    logging.basicConfig(
        level=logging.INFO,
        format="%(levelname)s | %(message)s",
    )

    try:

        # Find the dataset uploaded to Colab.
        dataset_path = find_dataset()

        print(
            f"\nUsing dataset:"
            f"\n{dataset_path}\n"
        )

        # Create validator.
        validator = (
            MedicalDatasetValidator(
                dataset_path
            )
        )

        # Run validation.
        report = validator.validate()

        # Display report.
        print_report(report)

    except FileNotFoundError as error:

        print()
        print(
            "ERROR:"
        )
        print(error)

    except Exception as error:

        print()
        print(
            "UNEXPECTED ERROR:"
        )
        print(error)

